import{_ as l,l as o,o as r,c as n,v as e,p as s,x as i,d as p,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"自然利率 r*","description":"","frontmatter":{"title":"自然利率 r*","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/r-star.md","filePath":"econ/r-star.md","lastUpdated":1789023840000}'),h={name:"econ/r-star.md"};function E(m,a,A,u,_,b){const t=o("Mermaid");return r(),n("div",null,[a[1]||(a[1]=e('<h1 id="自然利率-r" tabindex="-1">自然利率 r* <a class="header-anchor" href="#自然利率-r" aria-label="Permalink to &quot;自然利率 r*&quot;">​</a></h1><div class="epigraph"><p>自然利率是灵活价格下使储蓄与投资一致、物价既不加速也不减速的实际利率；政策利率相对它的位置，才是松紧。</p><footer>—— Wicksell, Geldzins und Güterpreise, 1898；Woodford 把同一对象写成新凯恩斯的 $r^n$</footer></div><p><a href="/econ/lucas-critique">上一课</a>禁止用旧简化式模拟新政。要写一条利率规则，必须先有一个<strong>不随名义规则漂移的</strong>实际基准：灵活价格均衡的实际利率。本课的缺口是把这个对象叫 \\(r^*\\)（或 Woodford 的 \\(r^n\\)），并声明它可被真实冲击移动。泰勒规则是下一课才把 \\(i\\) 写成对 \\(\\pi\\) 与缺口的反馈。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>动态 IS 已经把需求写成 \\(i-\\mathbb{E}\\pi\\) 对 \\(r^n\\) 的差。若把 \\(r^n\\) 当常数，任何 \\(i\\) 的下降都像宽松。Wicksell 的缺口是：信贷利率低于自然利率时，物价累积上升；高于则下降。自然利率由实物侧的储蓄、投资、生产率决定，不是央行印出来的。卢卡斯批判在此具体化：用旧样本估一个「中性基金利率」再拿去模拟新政，等于把当时增长、偏好与规则压缩进一个数字。</p><p>没有这个对象，泰勒规则的截距没有结构含义，NKPC 上的缺口也没有对照。本课结束周期课序里「自然率」这一侧：灵活价格均衡的实际利率。测量对照只点 Laubach–Williams 一句——滤波不是定义。</p><p><span class="marginnote">教学上 \\(r^*\\) 可当慢变常数。结构上它随趋势增长、人口、财政、风险溢价而变。Laubach 与 Williams 的滤波是测量对照，不是定义：定义仍是灵活价格均衡实际利率。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在已经学过的装置里，\\(r^*\\) 是把 \\(\\theta\\to 0\\)（或 Calvo 频率无限）后，欧拉与资源约束解出的实际利率路径。稳态附近它近似 \\(\\rho+g/\\sigma\\) 一类：时间偏好加消费增长。周期上，正的政府购买或正的偏好冲击会暂时抬高 \\(r^n\\)，技术冲击的符号取决于收入与替代。政策要稳定 \\(\\tilde{y}\\)，必须让 \\(i-\\mathbb{E}\\pi\\) 跟踪 \\(r^n\\)，而不是跟踪某个历史均值。</p>',9)),(r(),s(c,null,{default:i(()=>[d(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20FLEX%5B%22%E7%81%B5%E6%B4%BB%E4%BB%B7%E6%A0%BC%E5%9D%87%E8%A1%A1%22%5D%20--%3E%20RSTAR%5B%22r*%20%2F%20r%E2%81%BF%22%5D%0A%20%20REAL%5B%22%E5%81%8F%E5%A5%BD%E3%80%81%E6%8A%80%E6%9C%AF%E3%80%81%E8%B4%A2%E6%94%BF%22%5D%20--%3E%20RSTAR%0A%20%20I%5B%22%E6%94%BF%E7%AD%96%E5%88%A9%E7%8E%87%20i%22%5D%20--%3E%20GAP%5B%22i%E2%88%92E%CF%80%20%E2%88%92%20r*%22%5D%0A%20%20RSTAR%20--%3E%20GAP%0A%20%20GAP%20--%3E%20IS%5B%22%E5%8A%A8%E6%80%81%20IS%20%E7%9A%84%E7%BC%BA%E5%8F%A3%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<p>Wicksell 原著是累积过程，没有 Calvo。Woodford 的翻译是：利率主义不需要外生 \\(M\\)，但需要一个自然利率作为参照。数量论仍描述长期 \\(P\\)；短松紧是实际利率相对 \\(r^*\\)。</p><h3 id="不可观测不是不可定义" tabindex="-1">不可观测不是不可定义 <a class="header-anchor" href="#不可观测不是不可定义" aria-label="Permalink to &quot;不可观测不是不可定义&quot;">​</a></h3><p>\\(r^*\\) 与自然产出一样不能直接读出。这不把对象取消，只要求：规则与估计必须声明结构。把基金利率的 HP 滤波当 \\(r^*\\)，会把政策自己的历史写进「自然」。批判再次适用。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>\\(i-\\mathbb{E}\\pi\\lt r^*\\) 时，动态 IS 给出正缺口，NKPC 上 \\(\\pi\\) 升；反向为紧。长期中性：\\(\\tilde{y}=0\\)，\\(i=\\pi^*+r^*\\)。铸币税与 \\(\\pi^*\\) 的选择改变名义锚，不永久改变 \\(r^*\\)——除非通胀税扭曲了资本积累，那是超中性，要单独声明。</p><p>真实冲击移动 \\(r^*\\) 时，「按兵不动」的名义利率已经是政策变化。这正是规则必须写成对状态的反应、而不是钉死 \\(i\\) 的原因。RBC 对照里全部周期都是 \\(r^*\\) 与自然产出在动；NK 则还允许 \\(i-\\mathbb{E}\\pi\\) 偏离 \\(r^*\\)。泰勒规则把 \\(r^*\\) 当截距：截距估错，整条反应看起来永远偏松或偏紧，批判针对的就是把截距当不变结构。</p><p><span class="marginnote">开放经济下世界 \\(r^*\\) 与本国 \\(r^*\\) 可以分开，资本流动把二者往一起拉。本课封闭。CIP 与套息不是 \\(r^*\\) 的定义，见 <code>/quant/irp</code>。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不估计 HLW 曲线，不把自然利率写成金融条件指数。也不把 \\(r^*\\) 等同于黄金律资本的边际产出：后者是稳态计划者对象，前者是每个时点的灵活价格均衡利率，可以含风险与各种冲击。量化栏没有宏观 \\(r^*\\)。期限溢价、CIP 基差是资产价格，不是灵活价格均衡的 \\(r^n\\)；需要时链到 <code>/quant/irp</code>。</p><p>Wicksell 的累积过程没有 Calvo，也没有泰勒原理。本课用它当定义来源，机制已经换成欧拉 + 灵活价格出清。测量文献把 \\(r^*\\) 滤成慢变趋势，是对照，不是把定义改成滤波。泰勒规则下一课才把 \\(r^*\\) 当截距写进反馈；本课结束的是周期课序里这个对象本身。</p><p>后课默认：谈松紧，先说 \\(i-\\mathbb{E}\\pi\\) 相对 \\(r^*\\)。下一课把政策写成对通胀与缺口的反应函数，并以 \\(r^*\\) 当截距。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(r^*\\) 是灵活价格均衡实际利率，Wicksell 的自然利率。</li><li>政策松紧是 \\(i-\\mathbb{E}\\pi-r^*\\)，不是 \\(i\\) 的绝对水平。</li><li>\\(r^*\\) 随真实冲击而动；当常数是教学。</li><li>用旧样本估中性利率去模拟新政，再犯卢卡斯批判。</li><li>黄金律资本的边际产出不是同一个对象。</li><li>出处：Wicksell 1898；Woodford 的 \\(r^n\\)；Laubach–Williams 仅作测量对照。</li></ul>',13))])}const P=l(h,[["render",E]]);export{B as __pageData,P as default};
